  string selection=options["nodeID"]?.GetValue<string>()??"root";JsonNode root=artifact["tree"]!,selected=root;bool found=selection=="root";var pending=new Stack<JsonNode>();pending.Push(root);while(!found&&pending.Count>0){var node=pending.Pop();if(node["nodeID"]!.ToString()==selection){selected=node;found=true;break;}foreach(var child in node["children"]!.AsArray())pending.Push(child!);}if(!found)return new JsonObject{["status"]="node-not-found",["requiresRefresh"]=true,["version"]=artifact["version"]!.DeepClone()};
