  string scope=artifact["function"]+"|"+artifact["provider"]+"|"+artifact["target"]+"|"+artifact["channel"]+"|"+artifact["owner"];var result=new JsonObject{["status"]=artifact["status"]!.DeepClone(),["freshness"]=artifact["freshness"]?.DeepClone(),["scope"]=scope,["version"]=artifact["version"]!.DeepClone(),["bodyHash"]=artifact["bodyHash"]!.DeepClone(),["contractHash"]=artifact["contractHash"]!.DeepClone(),["selection"]=selection,["rootID"]=root["nodeID"]!.DeepClone(),["nodes"]=nodes,["truncated"]=queue.Count>0||selected["children"]!.AsArray().Count>offset+size,["descriptionPreview"]=artifact["description"]!.ToString()[..Math.Min(1024,artifact["description"]!.ToString().Length)],["descriptionTruncated"]=artifact["description"]!.ToString().Length>1024,["semanticReview"]="not-performed",["analysisCost"]="full selected-function parse may be required; bounded delivery does not imply incremental analysis"};result["viewHash"]=Hash(result.ToJsonString());if(Encoding.UTF8.GetByteCount(result.ToJsonString())>32768)throw new ArgumentException("Bounded projection response too large; request fewer nodes");return result;
